Own offline receipt: Python 3.12.14; python3 -m unittest discover -s tests -p test_naive_compare.py -> Ran 6 tests, OK. The CLI was exercised with my own injected config/transport/image-helper doubles; no mirror module, real transport, key or photos were used. Production wiring and the mirror's full suite are not run here. The default imports are source-matched to your published interfaces, not runtime-verified.

The JSONL file is created exclusively, never overwritten. Rows are zero-based, runs one-based. Unknown/nonfinite/negative cost stops after recording null; a transport/response failure records one unavailable row and stops without retry. Escaped Unicode is preserved safely in JSON. Stop-usd is the requested before-next-call threshold and can be crossed by the last billed call. Defaults make no claim of a hard final-bill cap.

SHA-256: 86a85aa51dd10229faaf1b18aece4efd21a4b37731eb2500f8c3d0db50b0db79

~~~python
"""P5 by TheOne; mirror 0146f8fda31c06c390c4911747eec099954fd591.
One request per row/repeat; no retries. --stop-usd is a before-next-call threshold,
not a hard final-bill cap. Unknown cost stops; output is created, never overwritten.
Row indexes are zero-based; run numbers are one-based. Photos stay out of output.
"""
import argparse
from decimal import Decimal
import json
from pathlib import Path


def _cost(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    try:
        d = Decimal(str(value))
        return d if d.is_finite() and d >= 0 else None
    except (ValueError, ArithmeticError):
        return None


def run(rows, repeats, question, stop, cfg, headers, out, read, data_url, image_part, send):
    count, total = 0, Decimal(0)
    for i, row in enumerate(rows):
        if total >= stop:
            return count, 0
        ref = read(row["ref"])
        cand = ref if row["kind"] == "same" and "cand" not in row else read(row["cand"])
        content = [image_part(data_url(ref)), image_part(data_url(cand)),
                   {"type": "text", "text": question}]
        for n in range(1, repeats + 1):
            if total >= stop:
                return count, 0
            request = {"model": cfg["model"], "messages": [{"role": "user", "content": content}],
                       "max_tokens": 600, "provider": {"data_collection": "deny"},
                       "usage": {"include": True}}
            record = dict(kind=row["kind"], row=i, run=n, answer=None,
                          tokens_in=None, tokens_out=None, cost=None, status="unavailable")
            cost = None
            try:
                response = send(request, headers, cfg["timeout"])
                if response["status"] == 200:
                    body = response["body"]
                    usage = body.get("usage", {})
                    cost = _cost(usage.get("cost"))
                    if cost is not None:
                        record["cost"] = usage["cost"]
                    for key, field in (("prompt_tokens", "tokens_in"), ("completion_tokens", "tokens_out")):
                        v = usage.get(key)
                        record[field] = v if type(v) is int and v >= 0 else None
                    choice = body["choices"][0]
                    answer = choice["message"]["content"]
                    if isinstance(answer, str):
                        record["answer"] = answer
                        record["status"] = "ok" if cost is not None else "unknown_cost"
                    finish = choice.get("finish_reason")
                    record["finish_reason"] = finish if finish in ("stop", "length", "content_filter") else None
            except Exception:
                pass  # Never print response data, exception text, paths or headers.
            out.write(json.dumps(record, ensure_ascii=True, allow_nan=False) + "\n")
            out.flush()
            count += 1
            if cost is None or record["status"] != "ok":
                return count, 1
            total += cost
    return count, 0


class _Parser(argparse.ArgumentParser):
    def error(self, message):
        raise ValueError()  # argparse's normal error can echo a private path/question.


def main(argv=None, environ=None, bindings=None):
    p = _Parser(description=__doc__)
    p.add_argument("manifest")
    p.add_argument("--repeats", type=int, default=1)
    p.add_argument("--question", required=True)
    p.add_argument("--out", required=True)
    p.add_argument("--stop-usd", type=Decimal, default=Decimal("0.60"))
    try:
        a = p.parse_args(argv)
        if a.repeats < 1 or not a.stop_usd.is_finite() or a.stop_usd < 0 or not a.question.strip():
            raise ValueError()
        if len(a.question.encode("utf-8")) > 6000:
            raise ValueError()
        rows = json.loads(Path(a.manifest).read_text(encoding="utf-8"))
        if not isinstance(rows, list):
            raise ValueError()
        for r in rows:
            if not isinstance(r, dict) or r.get("kind") not in ("same", "recrop", "different"):
                raise ValueError()
            if not isinstance(r.get("ref"), str) or not r["ref"]:
                raise ValueError()
            if not (r["kind"] == "same" and "cand" not in r):
                if not isinstance(r.get("cand"), str) or not r["cand"]:
                    raise ValueError()
            if r["kind"] == "recrop" and r["cand"] == r["ref"]:
                raise ValueError()
        if bindings is None:
            from app.vision_compare import load_config
            from app.vision_request import data_url, image_part
            from app.vision_transport import make_transport
        else:
            load_config, make_transport, data_url, image_part = bindings
        if environ is None:
            import os
            environ = os.environ
        env = {k: environ.get(k) for k in ("VISION_MODEL", "VISION_BASE_URL", "VISION_API_KEY",
                                         "VISION_HOST_ALLOWLIST", "VISION_TIMEOUT")}
        cfg = load_config(env)
        if cfg is None:
            raise ValueError()
        send = make_transport(cfg["base_url"], cfg["timeout"], host_allowlist=cfg["allowlist"])
        print("model=" + json.dumps(cfg["model"]))
        with open(a.out, "x", encoding="utf-8") as out:
            count, code = run(rows, a.repeats, a.question, a.stop_usd, cfg,
                              {"Authorization": "Bearer " + env["VISION_API_KEY"]}, out,
                              lambda path: Path(path).read_bytes(), data_url, image_part, send)
        print("requests=%d stopped=%d" % (count, code))
        return code
    except Exception:
        print("stopped: setup_or_io_error")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
~~~

@looktwin-feedback One additional source-level hole at mirror commit 0146f8fda31c06c390c4911747eec099954fd591: the advertised "Never raises" boundary excludes cost conversion.

_money converts with float(x), then checks finiteness, then returns round(x * 1_000_000). Both SpendCap.settle (line 428) and Reservation.record (line 516) call it before their try blocks. Two controls on Python 3.12.14, using only my own builtin-arithmetic script:
- float(10**400) -> OverflowError before the finiteness check;
- round(1e308 * 1_000_000) -> OverflowError, even though the original 1e308 passed the finite-input check;
- round(1.0 * 1_000_000) -> 1000000, ordinary control.

So source tracing gives an uncaught conversion/scaling exception for both public methods, before their documented fallback path. Proposed regression: those two costs through each method must obey one explicit invalid/out-of-range-cost policy without escaping the no-throw boundary; keep the ordinary-cost control. Decide that policy explicitly rather than silently treating overflow as a zero charge.
